begin;
select no_plan();
select ok((select prosecdef and provolatile='v' and ('search_path=""'=any(proconfig) or 'search_path='=any(proconfig)) from pg_proc where oid='api.initialize_current_owner_blocks_from_link(jsonb)'::regprocedure),'Hardened volatile empty-path definer');
select ok(not has_function_privilege('anon','api.initialize_current_owner_blocks_from_link(jsonb)','EXECUTE'),'anon execution withheld');
set local role anon;
select throws_ok($$select api.initialize_current_owner_blocks_from_link('{}')$$,'42501',null,'Actual anon denied');
reset role;
select ok(not has_function_privilege('authenticated','api.initialize_current_owner_blocks_from_link(jsonb)','EXECUTE'),'authenticated execution withheld');
set local role authenticated;
select throws_ok($$select api.initialize_current_owner_blocks_from_link('{}')$$,'42501',null,'Actual authenticated denied');
reset role;
select ok(not has_function_privilege('service_role','api.initialize_current_owner_blocks_from_link(jsonb)','EXECUTE'),'service_role execution withheld');
set local role service_role;
select throws_ok($$select api.initialize_current_owner_blocks_from_link('{}')$$,'42501',null,'Actual service_role denied');
reset role;
select ok(not exists(select 1 from information_schema.routine_privileges where routine_schema='api' and routine_name='initialize_current_owner_blocks_from_link' and grantee='PUBLIC'),'PUBLIC execution withheld');
set local request.jwt.claims='{}';
select is(api.initialize_current_owner_blocks_from_link('{}'),'{"status":"unauthenticated"}'::jsonb,'No actor');
set local request.jwt.claims='{"sub":"a4000000-0000-4000-8000-000000000099","user_metadata":{"owner_id":"forged"}}';
select is(api.initialize_current_owner_blocks_from_link('{}'),'{"status":"owner_missing"}'::jsonb,'Metadata not authority');
insert into auth.users(id,email) values
 ('a4000000-0000-4000-8000-000000000001','manual-one@example.test'),
 ('a4000000-0000-4000-8000-000000000002','manual-two@example.test'),
 ('a4000000-0000-4000-8000-000000000003','manual-missing@example.test');
create temporary table actors as select auth_user_id,owner_id from core.owner_auth_bindings where auth_user_id in
 ('a4000000-0000-4000-8000-000000000001','a4000000-0000-4000-8000-000000000002','a4000000-0000-4000-8000-000000000003');
update core.owner_onboarding_progress set current_step='preview_publish',primary_use_case='business' where owner_id in (select owner_id from actors);
insert into core.owner_handle_namespaces(normalized_handle,owner_id,namespace_kind)
 select 'manual-'||right(auth_user_id::text,6),owner_id,'current' from actors;
set local request.jwt.claims='{"sub":"a4000000-0000-4000-8000-000000000001"}';
select is(api.initialize_current_owner_blocks_from_connection('{}'),'{"status":"owner_not_eligible"}'::jsonb,'Incomplete Owner cannot initialize');
update core.owners set onboarding_completed_at=now() where id in (select owner_id from actors);
insert into core.identity_connection_working(owner_id,connection_kind,social_platform,destination_url,revision)
 select owner_id,case when auth_user_id='a4000000-0000-4000-8000-000000000001' then 'generic_link'::core.identity_connection_kind else 'social'::core.identity_connection_kind end,
 case when auth_user_id='a4000000-0000-4000-8000-000000000001' then null else 'custom_platform-1' end,
 'HTTPS://Private.example.test/Exact?X=1#Recoverable',3 from actors where auth_user_id<>'a4000000-0000-4000-8000-000000000003';

-- Manual initialization race fixtures end here.
