update core.owners set account_state='restricted' where id=(select owner_id from actors where auth_user_id='a4000000-0000-4000-8000-000000000001');
select is(api.initialize_current_owner_blocks_from_link('{"action": "initialize_link_block", "base_collection_revision": null, "is_visible": false, "link_working": {"kind": "generic_link", "title": " <script>raw</script> ", "social_platform": "unexpected", "destination_url": "javascript:private"}}'::jsonb),'{"status":"owner_not_eligible"}'::jsonb,'restricted denied');
update core.owners set account_state='suspended' where id=(select owner_id from actors where auth_user_id='a4000000-0000-4000-8000-000000000001');
select is(api.initialize_current_owner_blocks_from_link('{"action": "initialize_link_block", "base_collection_revision": null, "is_visible": false, "link_working": {"kind": "generic_link", "title": " <script>raw</script> ", "social_platform": "unexpected", "destination_url": "javascript:private"}}'::jsonb),'{"status":"owner_not_eligible"}'::jsonb,'suspended denied');
update core.owners set account_state='active' where id=(select owner_id from actors where auth_user_id='a4000000-0000-4000-8000-000000000001');
update core.owners set onboarding_completed_at=null where id=(select owner_id from actors where auth_user_id='a4000000-0000-4000-8000-000000000001');
select is(api.initialize_current_owner_blocks_from_link('{"action": "initialize_link_block", "base_collection_revision": null, "is_visible": false, "link_working": {"kind": "generic_link", "title": " <script>raw</script> ", "social_platform": "unexpected", "destination_url": "javascript:private"}}'::jsonb),'{"status":"owner_not_eligible"}'::jsonb,'Incomplete denied');
update core.owners set onboarding_completed_at=(select onboarding_completed_at from original_owners where id=(select owner_id from actors where auth_user_id='a4000000-0000-4000-8000-000000000001')) where id=(select owner_id from actors where auth_user_id='a4000000-0000-4000-8000-000000000001');
update core.owner_onboarding_progress set primary_use_case=null where owner_id=(select owner_id from actors where auth_user_id='a4000000-0000-4000-8000-000000000001');
select is(api.initialize_current_owner_blocks_from_link('{"action": "initialize_link_block", "base_collection_revision": null, "is_visible": false, "link_working": {"kind": "generic_link", "title": " <script>raw</script> ", "social_platform": "unexpected", "destination_url": "javascript:private"}}'::jsonb),'{"status":"unavailable"}'::jsonb,'Missing context denied');
update core.owner_onboarding_progress set primary_use_case='business' where owner_id=(select owner_id from actors where auth_user_id='a4000000-0000-4000-8000-000000000001');
create function pg_temp.fail_after_initialize() returns void language plpgsql as $$ begin perform api.initialize_current_owner_blocks_from_link('{"action": "initialize_link_block", "base_collection_revision": null, "is_visible": false, "link_working": {"kind": "generic_link", "title": " <script>raw</script> ", "social_platform": "unexpected", "destination_url": "javascript:private"}}'::jsonb); raise exception 'forced rollback' using errcode='P0001'; end; $$;
select throws_ok('select pg_temp.fail_after_initialize()','P0001','forced rollback','Failure rolls back all inserts');
select is((select count(*)::integer from core.identity_block_collections_working where owner_id in (select owner_id from actors)),0,'Denials/rollback leave no collection');
create function pg_temp.reject_manual_payload() returns trigger language plpgsql as $$ begin raise exception 'payload insert failed' using errcode='P0001'; end; $$;
create trigger reject_manual_payload before insert on core.identity_block_links_working for each row execute function pg_temp.reject_manual_payload();
select throws_ok($$select api.initialize_current_owner_blocks_from_link('{"action":"initialize_link_block","base_collection_revision":null,"is_visible":false,"link_working":{"kind":"generic_link","title":null,"social_platform":null,"destination_url":null}}')$$,'P0001','payload insert failed','Payload failure rolls back collection and membership');
drop trigger reject_manual_payload on core.identity_block_links_working;
select is((select count(*)::integer from core.identity_block_collections_working where owner_id in (select owner_id from actors)),0,'Payload failure leaves no collection');
select is((select count(*)::integer from core.identity_blocks_working where owner_id in (select owner_id from actors)),0,'Payload failure leaves no orphan membership');
create temporary table reply as select api.initialize_current_owner_blocks_from_link('{"action": "initialize_link_block", "base_collection_revision": null, "is_visible": false, "link_working": {"kind": "generic_link", "title": " <script>raw</script> ", "social_platform": "unexpected", "destination_url": "javascript:private"}}'::jsonb) value;
select is((select value->>'status' from reply),'success','Manual raw Generic succeeds');
select is((select value->'collection_revision' from reply),'1'::jsonb,'Creation revision1');
select is((select count(*)::integer from reply,jsonb_object_keys(value)),3,'Exact minimal ack');
select ok((select value->>'block_id' ~ '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$' from reply),'Server UUID');
select is((select jsonb_build_object('kind',kind,'position',position,'visible',is_visible) from core.identity_blocks_working where owner_id=(select owner_id from actors where auth_user_id='a4000000-0000-4000-8000-000000000001')),'{"kind": "generic_link", "position": 1, "visible": false}'::jsonb,'Own first hidden membership');
select is((select jsonb_build_object('kind',kind,'title',title,'social_platform',social_platform,'destination_url',destination_url) from core.identity_block_links_working where owner_id=(select owner_id from actors where auth_user_id='a4000000-0000-4000-8000-000000000001')),'{"kind": "generic_link", "title": " <script>raw</script> ", "social_platform": "unexpected", "destination_url": "javascript:private"}'::jsonb,'Raw matching payload retained');
select is(api.initialize_current_owner_blocks_from_link('{"action": "initialize_link_block", "base_collection_revision": null, "is_visible": false, "link_working": {"kind": "generic_link", "title": " <script>raw</script> ", "social_platform": "unexpected", "destination_url": "javascript:private"}}'::jsonb),'{"status":"already_initialized"}'::jsonb,'Repeat is conflict, not successful replay');
delete from core.identity_blocks_working where owner_id=(select owner_id from actors where auth_user_id='a4000000-0000-4000-8000-000000000001');
select is(api.initialize_current_owner_blocks_from_link('{"action": "initialize_link_block", "base_collection_revision": null, "is_visible": false, "link_working": {"kind": "generic_link", "title": " <script>raw</script> ", "social_platform": "unexpected", "destination_url": "javascript:private"}}'::jsonb),'{"status":"already_initialized"}'::jsonb,'Explicit empty never replaced');
select is((select revision::integer from core.identity_block_collections_working where owner_id=(select owner_id from actors where auth_user_id='a4000000-0000-4000-8000-000000000001')),1,'Empty conflict preserves revision');
set local request.jwt.claims='{"sub":"a4000000-0000-4000-8000-000000000003"}';
create temporary table social_reply as select api.initialize_current_owner_blocks_from_link('{"action": "initialize_link_block", "base_collection_revision": null, "is_visible": true, "link_working": {"kind": "social", "title": null, "social_platform": null, "destination_url": null}}'::jsonb) value;
select is((select value->>'status' from social_reply),'success','No source needed, null Social accepted');
select ok((select block_id<>(select (value->>'block_id')::uuid from reply) and kind='social' and is_visible and position=1 from core.identity_blocks_working where block_id=(select (value->>'block_id')::uuid from social_reply)),'Distinct Owner UUID/visible Social');
select ok((select title is null and social_platform is null and destination_url is null from core.identity_block_links_working where block_id=(select (value->>'block_id')::uuid from social_reply)),'Nulls retained');
set local request.jwt.claims='{"sub":"a4000000-0000-4000-8000-000000000002"}';
create temporary table boundary_reply as select api.initialize_current_owner_blocks_from_link(jsonb_build_object('action','initialize_link_block','base_collection_revision',null,'is_visible',false,'link_working',jsonb_build_object('kind','social','title',repeat('🙂',512),'social_platform',repeat('🙂',40),'destination_url',repeat('🙂',2048)))) value;
select is((select value->>'status' from boundary_reply),'success','Exact Unicode bounds accepted');
select ok((select char_length(title)=512 and char_length(social_platform)=40 and char_length(destination_url)=2048 from core.identity_block_links_working where block_id=(select (value->>'block_id')::uuid from boundary_reply)),'Code points preserved');
select is((select count(*)::integer from core.identity_block_initialization_provenance where owner_id in (select owner_id from actors)),0,'No fabricated import provenance');
select ok(not exists((select * from core.identity_connection_working except select * from original_identity_connection_working) union all (select * from original_identity_connection_working except select * from core.identity_connection_working)),'Unchanged identity_connection_working');
select ok(not exists((select * from core.identity_block_initialization_provenance except select * from original_identity_block_initialization_provenance) union all (select * from original_identity_block_initialization_provenance except select * from core.identity_block_initialization_provenance)),'Unchanged identity_block_initialization_provenance');
select ok(not exists((select * from core.identity_working except select * from original_identity_working) union all (select * from original_identity_working except select * from core.identity_working)),'Unchanged identity_working');
select ok(not exists((select * from core.identity_layout_working except select * from original_identity_layout_working) union all (select * from original_identity_layout_working except select * from core.identity_layout_working)),'Unchanged identity_layout_working');
select ok(not exists((select * from core.identity_publications except select * from original_identity_publications) union all (select * from original_identity_publications except select * from core.identity_publications)),'Unchanged identity_publications');
select ok(not exists((select * from core.onboarding_preview_receipts except select * from original_onboarding_preview_receipts) union all (select * from original_onboarding_preview_receipts except select * from core.onboarding_preview_receipts)),'Unchanged onboarding_preview_receipts');
select ok(not exists((select * from core.owner_auth_bindings except select * from original_owner_auth_bindings) union all (select * from original_owner_auth_bindings except select * from core.owner_auth_bindings)),'Unchanged owner_auth_bindings');
select ok(not exists((select * from core.owner_handle_namespaces except select * from original_owner_handle_namespaces) union all (select * from original_owner_handle_namespaces except select * from core.owner_handle_namespaces)),'Unchanged owner_handle_namespaces');
select ok(not exists((select * from core.owners except select * from original_owners) union all (select * from original_owners except select * from core.owners)),'Unchanged owners');
select * from finish();
rollback;
